						);
					}
					return { contents, loader: "js" };
				});
			},
		},
	],
});
mkdirSync(artifactDir, { recursive: true });
writeFileSync(join(artifactDir, "metafile.json"), `${JSON.stringify(result.metafile, null, 2)}\n`);

