			const valid =
				(!stored?.scope && providerId !== "openai-codex") || stored?.scope === (await this.scopeFor(providerId));
			if (valid && stored?.models) this.overlay.setLive(providerId, stored.models);
			else this.overlay.setLive(providerId, []);
