async function login(interaction: AuthInteraction): Promise<ExternalClaudeCodeCredential> {
	interaction.notify({ type: "info", message: "Claude Code handles subscription authentication and one generation per lunR request. lunR still owns tools, permissions, history, compaction, and subagents. Python 3.10+ and Claude Code are required. No credentials are copied into lunR." });
	let python = await pythonInterpreter();
	if (!python) {
		interaction.notify({ type: "info", message: "Install Python 3.10+ from https://www.python.org/downloads/ . This is a separate operating-system installation, not part of lunR." });
		const packageManager = process.platform === "darwin" ? await executable("brew")
			: process.platform === "linux" ? await executable("apt-get") ?? await executable("dnf") : undefined;
		const installer = process.platform === "win32" ? { command: "winget", args: ["install", "--id", "Python.Python.3.13", "-e"] }
			: packageManager?.endsWith("apt-get") ? { command: "sudo", args: [packageManager, "install", "-y", "python3"] }
			: packageManager?.endsWith("dnf") ? { command: "sudo", args: [packageManager, "install", "-y", "python3"] }
			: packageManager ? { command: packageManager, args: ["install", "python@3.13"] } : undefined;
		const choice = await interaction.prompt({ type: "select", message: "Python 3.10+ is missing. A system installer may request administrator access and change your machine.",
			options: [...(installer ? [{ id: "install", label: `Install through ${installer.command} ${installer.args.join(" ")}` }] : []),
				{ id: "cancel", label: "Cancel and install Python yourself" }] });
		if (choice === "install" && installer) await install(installer.command, installer.args, interaction);
		else throw new Error("Install Python 3.10+ and retry /login anthropic");
		python = await pythonInterpreter();
		if (!python) throw new Error("Python installation finished but the interpreter is not on PATH. Restart lunR and retry.");
	}
	let command = await executable("claude");
	if (!command) {
		const choice = await interaction.prompt({ type: "select", message: "Claude Code is missing. Installation changes your user-level system and may require a new PATH.",
			options: [{ id: "install", label: "Install Claude Code" }, { id: "existing", label: "Use existing executable" }, { id: "cancel", label: "Cancel" }] });
		if (choice === "install") {
			if (process.platform === "win32") await install("powershell", ["-NoProfile", "-Command", "irm https://claude.ai/install.ps1 | iex"], interaction);
			else await install("sh", ["-c", "curl -fsSL https://claude.ai/install.sh | bash"], interaction);
			command = await executable("claude");
		} else if (choice === "existing") {
			const path = await interaction.prompt({ type: "text", message: "Absolute path to Claude Code executable:" });
			if (!isAbsolute(path)) throw new Error("Claude Code path must be absolute");
			command = await executable(path);
		} else throw new Error("Anthropic subscription setup cancelled");
	}
	if (!command) throw new Error("Claude Code executable not found. Restart lunR after installation and retry.");
	const version = await setupProbe(python, command, "version") as string;
	if (!new RegExp(`^${VERSION.replaceAll(".", "\\.")}(?:\\s|$)`).test(version)) throw new Error(`Claude Code ${VERSION} is the only qualified version. Found ${version.slice(0, 40)}. Subscription requests are disabled until this version is qualified.`);
	let status = await setupProbe(python, command, "status") as { logged_in?: boolean; plan?: string; accountFingerprint?: string }; 
	if (!status.logged_in || !/Claude (Pro|Max|Team|Enterprise)/i.test(status.plan ?? "")) {
		interaction.notify({ type: "info", message: `Run ${command} auth login in another terminal and select a Claude subscription, then retry here. Console/API-key authentication is not a subscription.` });
		const choice = await interaction.prompt({ type: "select", message: "After signing into Claude Code, check subscription status again?",
			options: [{ id: "retry", label: "Check again" }, { id: "cancel", label: "Cancel" }] });
		if (choice !== "retry") throw new Error("Anthropic subscription setup cancelled");
		status = await setupProbe(python, command, "status") as typeof status;
		if (!status.logged_in || !/Claude (Pro|Max|Team|Enterprise)/i.test(status.plan ?? "")) throw new Error("Claude Code is not signed into a Claude subscription");
	}
	const discovered = await setupProbe(python, command, "discover");
	if (!Array.isArray(discovered) || !discovered.length || discovered.some((row) => !row || typeof row.id !== "string" || row.upstream_requests !== 0)) {
		throw new Error("Claude Code model discovery did not verify zero Messages requests. Setup not saved.");
	}
	return { type: "external_claude_code", version: 1, manager: "claude-code", command, python, accountFingerprint: status.accountFingerprint ?? randomUUID(), routes: discovered.map((row) => row.id) };

